<?php
namespace App\Http\Controllers\Upload;use App\Http\Controllers\Controller;use Illuminate\Http\Request;
class UploadController extends Controller {public function store(Request $r){$f=$r->file('attachments',[]);if(!$f)return response()->json(['message'=>'Không có file nào được tải lên.'],400);if(!is_array($f))$f=[$f];if(count($f)>5)return response()->json(['message'=>'Too many files'],422);$urls=[];foreach($f as $x){if(!$x->isValid()||$x->getSize()>5242880||!in_array(strtolower($x->getClientOriginalExtension()),['jpeg','jpg','png','gif','webp','pdf']))return response()->json(['message'=>'Chỉ hỗ trợ file hình ảnh (JPG, PNG, GIF, WEBP) hoặc PDF!'],422);$name='attachments-'.round(microtime(true)*1000).'-'.random_int(0,1000000000).'.'.$x->getClientOriginalExtension();$x->move(public_path('uploads'),$name);$urls[]=url('/public/uploads/'.$name);}return response()->json(['message'=>'Tải lên thành công!','urls'=>$urls]);}}
